CREATE OR REPLACE FUNCTION public.form_master_candidates(_school_id uuid) RETURNS TABLE(user_id uuid, full_name text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_manage_school(auth.uid(),_school_id) THEN RAISE EXCEPTION 'Only school administrators may assign form masters'; END IF; RETURN QUERY SELECT p.user_id,p.full_name FROM public.profiles p WHERE p.school_id=_school_id AND public.is_school_staff(p.user_id,_school_id) ORDER BY p.full_name; END $$;
REVOKE ALL ON FUNCTION public.form_master_candidates(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.form_master_candidates(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.assign_form_master(_school_id uuid,_class_id uuid,_teacher_id uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE saved public.classes; BEGIN IF NOT public.can_manage_school(auth.uid(),_school_id) OR NOT public.school_permission(auth.uid(),_school_id,'academics.edit') THEN RAISE EXCEPTION 'Only school administrators may assign form masters'; END IF;
PERFORM 1 FROM public.classes WHERE id=_class_id AND school_id=_school_id AND active AND NOT pending_activation FOR UPDATE;
IF NOT FOUND THEN RAISE EXCEPTION 'Choose an active class in this school'; END IF;
IF _teacher_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.user_id=_teacher_id AND p.school_id=_school_id AND public.is_school_staff(_teacher_id,_school_id)) THEN RAISE EXCEPTION 'Choose active school staff'; END IF;
DELETE FROM public.teacher_allocations WHERE class_id=_class_id AND school_id=_school_id AND is_class_teacher AND subject_id IS NULL;
UPDATE public.teacher_allocations SET is_class_teacher=false WHERE class_id=_class_id AND school_id=_school_id AND is_class_teacher;
UPDATE public.classes SET teacher_id=_teacher_id WHERE id=_class_id AND school_id=_school_id RETURNING * INTO saved;
IF saved.id IS NULL THEN RAISE EXCEPTION 'Class assignment was not saved'; END IF;
RETURN to_jsonb(saved); END $$;
REVOKE ALL ON FUNCTION public.assign_form_master(uuid,uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.assign_form_master(uuid,uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.can_enter_class_scores(_user_id uuid,_school_id uuid,_class_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.school_permission(_user_id,_school_id,'results.edit') AND EXISTS(SELECT 1 FROM public.classes c WHERE c.id=_class_id AND c.school_id=_school_id AND c.active AND NOT c.pending_activation) AND (public.can_manage_school(_user_id,_school_id) OR public.is_form_master(_user_id,_class_id) OR public.teaches_class(_user_id,_class_id)) $$;
REVOKE ALL ON FUNCTION public.can_enter_class_scores(uuid,uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_enter_class_scores(uuid,uuid,uuid) TO authenticated;
CREATE POLICY "Assigned class score inserts" ON public.assessments AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.can_enter_class_scores(auth.uid(),school_id,class_id));
CREATE POLICY "Assigned class score updates" ON public.assessments AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.can_enter_class_scores(auth.uid(),school_id,class_id)) WITH CHECK(public.can_enter_class_scores(auth.uid(),school_id,class_id));